import assert from 'node:assert/strict';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { test } from 'node:test';

import { GALLERY } from './gallery';

/**
 * The Storybook shows exactly the gallery (`research/PLAN_kit_components_storybook.md` §4.9, §5.2 item 20). Storybook
 * indexes a CSF file STATICALLY, so its stories cannot be generated by a loop over the gallery; each one is a line
 * `export const X = { args: { case: '<id>' } };` in `stories/<component>.stories.ts`. This test reads those files and
 * holds them equal to the gallery both ways — a case with no story, a story for no case, a component with no file.
 */

const STORIES = path.resolve(__dirname, '..', '..', 'stories');

interface StoryFile {
  readonly component: string | undefined;
  readonly cases: readonly string[];
  readonly hasMatrix: boolean;
}

/** What one CSF file declares: its component and the case each story names. */
export function readStories(text: string): StoryFile {
  return {
    component: /^const COMPONENT = '([A-Za-z]+)';$/m.exec(text)?.[1],
    cases: [...text.matchAll(/^export const [A-Z][A-Za-z]* = \{ args: \{ case: '([a-z0-9-]+)' \} \};$/gm)].map((match) => match[1] ?? ''),
    hasMatrix: /^export const Matrix = \{ render: \(\) => matrix\(COMPONENT\) \};$/m.test(text),
  };
}

function storyFiles(): Map<string, StoryFile> {
  const files = fs.readdirSync(STORIES).filter((name) => name.endsWith('.stories.ts'));

  return new Map(files.map((name) => [name, readStories(fs.readFileSync(path.join(STORIES, name), 'utf8'))]));
}

test('every gallery component has its stories file, named for it, with one story per case and a matrix — and nothing else', () => {
  const files = storyFiles();
  assert.deepEqual([...files.keys()].sort(), GALLERY.map((component) => `${component.id}.stories.ts`).sort());
  for (const component of GALLERY) {
    const file = files.get(`${component.id}.stories.ts`) ?? assert.fail(`no stories for ${component.id}`);
    assert.equal(file.component, component.id);
    assert.deepEqual([...file.cases].sort(), component.cases.map((entry) => entry.id).sort(), `${component.id}: the stories and the gallery disagree`);
    assert.ok(file.hasMatrix, `${component.id} has no Matrix story`);
  }
});

test('the reader finds a known story, the component and the matrix in a fixture, and ignores a line of another shape', () => {
  const fixture = [
    "const COMPONENT = 'tabs';",
    "export const Default = { args: { case: 'default' } };",
    "export const Other = { args: { case: 'other' }, parameters: {} };",
    'export const Matrix = { render: () => matrix(COMPONENT) };',
  ].join('\n');

  assert.deepEqual(readStories(fixture), { component: 'tabs', cases: ['default'], hasMatrix: true });
  assert.ok(storyFiles().get('dataTable.stories.ts')?.cases.includes('sorted-descending'), 'the real files were not read');
});
